function getUrlParameter(n){var f=location.href,r=f.split("?")[1],t="",u,i;if(typeof r!="undefined"&&r!=null&&r!="")for(u=r.split("&"),i=0;i<u.length;i++)u[i].split("=")[0]==n&&(t=u[i].split("=")[1]);return(t==undefined||t==null||t=="")&&(t=""),t}$(document).ready(function(){var n=getUrlParameter("state"),t=getUrlParameter("code");$("#code").val(t);$("#frmLogin").attr("action",n);frmLogin.submit()})